79	  const showToast = useToast();
80	
81	  const [booking, setBooking] = useState<Booking | null>(null);
82	  const [guardFailed, setGuardFailed] = useState(false);
83	  const [touched, setTouched] = useState<TouchedState>(INITIAL_TOUCHED);
84	  const [submitting, setSubmitting] = useState(false);
85	
86	  useEffect(() => {
87	    const existing = loadBooking();
88	    if (
89	      !existing ||
90	      existing.paid ||
91	      existing.screeningId !== Number(screeningId) ||
92	      existing.seats.length === 0
