102	  if (guardFailed || !booking) {
103	    return null;
104	  }
105	
106	  const values = booking.checkout;
107	  const errors = validate(values);
108	  const total = totalPrice(booking.seats);
109	
110	  function updateValues(partial: Partial<CheckoutValues>) {
111	    if (!booking) return;
112	    const updated = { ...booking, checkout: { ...booking.checkout, ...partial } };
113	    setBooking(updated);
114	    saveBooking(updated);
