127	    const currentErrors = validate(booking.checkout);
128	    if (Object.keys(currentErrors).length > 0) {
129	      setTouched({
130	        firstName: true,
131	        lastName: true,
132	        email: true,
133	        confirmEmail: true,
134	        phone: true,
