1	export const ROW_COUNT = 15;
2	export const COLUMN_COUNT = 24;
3	export const COUCH_ROW = 15;
4	export const ACCESSIBLE_ROW = 1;
5	export const ACCESSIBLE_COLUMNS = [10, 11, 12, 13, 14, 15];
6	export const MAX_SEATS = 10;
7	
8	export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';
9	
10	export function seatId(row: number, column: number): string {
11	  return `R${row}C${column}`;
12	}
13	
14	export function parseSeatId(id: string): { row: number; column: number } {
15	  const match = /^R(\d+)C(\d+)$/.exec(id);
16	  if (!match) {
17	    throw new Error(`Invalid seat id: ${id}`);
18	  }
19	  return { row: Number(match[1]), column: Number(match[2]) };
20	}
21	
22	export function isAccessible(row: number, column: number): boolean {
23	  return row === ACCESSIBLE_ROW && ACCESSIBLE_COLUMNS.includes(column);
24	}
25	
26	/** Columns that hold individual seats in a (non-couch) row. */
27	export function rowColumns(row: number): number[] {
28	  if (row === COUCH_ROW) {
29	    return [];
30	  }
31	  if (row <= 10) {
32	    return range(5, COLUMN_COUNT);
33	  }
34	  return range(1, COLUMN_COUNT);
35	}
36	
37	/** Couches in row 15, as [columnStart, columnEnd] pairs. */
38	export function couches(): [number, number][] {
39	  const pairs: [number, number][] = [];
40	  for (let c = 1; c < COLUMN_COUNT; c += 2) {
41	    pairs.push([c, c + 1]);
42	  }
43	  return pairs;
44	}
45	
46	function range(from: number, to: number): number[] {
47	  const result: number[] = [];
48	  for (let i = from; i <= to; i++) {
49	    result.push(i);
50	  }
51	  return result;
52	}
53	
54	export function seatPrice(row: number): number {
55	  if (row <= 5) return 25;
56	  if (row <= 10) return 32;
57	  if (row <= 14) return 39;
58	  throw new Error('Row 15 only has couches');
59	}
60	
61	export const COUCH_PRICE = 89;
62	
63	export function formatPrice(amount: number): string {
64	  return `${amount.toFixed(2)} PLN`;
65	}
66	
67	export function seatState(
68	  row: number,
69	  column: number,
70	  occupied: ReadonlySet<string>,
71	  selected: ReadonlySet<string>,
72	): SeatState {
73	  const id = seatId(row, column);
74	  if (occupied.has(id)) return 'unavailable';
75	  if (selected.has(id)) return 'selected';
76	  if (isAccessible(row, column)) return 'accessible';
77	  return 'available';
78	}
79	
80	export function couchState(
81	  row: number,
82	  columnStart: number,
83	  columnEnd: number,
84	  occupied: ReadonlySet<string>,
85	  selected: ReadonlySet<string>,
86	): SeatState {
87	  const idA = seatId(row, columnStart);
88	  const idB = seatId(row, columnEnd);
89	  if (occupied.has(idA) || occupied.has(idB)) return 'unavailable';
90	  if (selected.has(idA) && selected.has(idB)) return 'selected';
91	  return 'available';
92	}
93	
94	export interface SeatItem {
95	  row: number;
96	  type: 'seat' | 'couch';
97	  column?: number;
98	  columnStart?: number;
99	  columnEnd?: number;
100	  ids: string[];
101	  price: number;
102	}
103	
104	/** Selected seats and couches, derived from a flat list of seat identifiers. */
105	export function getBookingItems(seatIds: string[]): SeatItem[] {
106	  const byRow = new Map<number, number[]>();
107	  for (const id of seatIds) {
108	    const { row, column } = parseSeatId(id);
109	    const columns = byRow.get(row) ?? [];
110	    columns.push(column);
111	    byRow.set(row, columns);
112	  }
113	
114	  const items: SeatItem[] = [];
115	  for (const [row, columns] of byRow) {
116	    const sorted = [...columns].sort((a, b) => a - b);
117	    if (row === COUCH_ROW) {
118	      for (let i = 0; i < sorted.length; i += 2) {
119	        const columnStart = sorted[i];
120	        const columnEnd = sorted[i + 1];
121	        items.push({
122	          row,
123	          type: 'couch',
124	          columnStart,
125	          columnEnd,
126	          ids: [seatId(row, columnStart), seatId(row, columnEnd)],
127	          price: COUCH_PRICE,
128	        });
129	      }
130	    } else {
131	      for (const column of sorted) {
132	        items.push({ row, type: 'seat', column, ids: [seatId(row, column)], price: seatPrice(row) });
133	      }
134	    }
135	  }
136	
137	  items.sort((a, b) => {
138	    if (a.row !== b.row) return a.row - b.row;
139	    const aCol = a.type === 'couch' ? (a.columnStart as number) : (a.column as number);
140	    const bCol = b.type === 'couch' ? (b.columnStart as number) : (b.column as number);
141	    return aCol - bCol;
142	  });
143	
144	  return items;
145	}
146	
147	export function seatDescription(item: SeatItem): string {
148	  return item.type === 'couch' ? `Couch ${item.columnStart}-${item.columnEnd}` : `${item.column}`;
149	}
150	
151	export function totalPrice(seatIds: string[]): number {
152	  return getBookingItems(seatIds).reduce((sum, item) => sum + item.price, 0);
153	}
154	
155	export function seatCount(seatIds: string[]): number {
156	  return seatIds.length;
157	}
