6	export const ISO_DATE_FORMAT = 'YYYY-MM-DD';
7	
8	export function today(): Dayjs {
9	  return dayjs().startOf('day');
10	}
11	
12	/** A missing, invalid or past date resolves to today. */
13	export function parseDateParam(raw: string | null): Dayjs {
14	  const todayDate = today();
15	  if (!raw) {
16	    return todayDate;
17	  }
18	  const parsed = dayjs(raw, ISO_DATE_FORMAT, true);
19	  if (!parsed.isValid()) {
20	    return todayDate;
21	  }
22	  if (parsed.isBefore(todayDate, 'day')) {
23	    return todayDate;
24	  }
25	  return parsed;
26	}
27	
28	export function toISODate(date: Dayjs): string {
29	  return date.format(ISO_DATE_FORMAT);
30	}
31	
32	/** `<Weekday> <D> <Mon> <HH:mm>`, e.g. "Tuesday 15 Sep 16:00". */
33	export function formatShowDate(date: string, time: string): string {
34	  return dayjs(`${date}T${time}`, `${ISO_DATE_FORMAT}THH:mm`).format('dddd D MMM HH:mm');
35	}
