31	export function emptyBooking(screeningId: number): Booking {
32	  return {
33	    screeningId,
34	    seats: [],
35	    checkout: emptyCheckout(),
36	    paid: false,
37	    customerEmail: null,
38	  };
39	}
40	
41	function isBooking(value: unknown): value is Booking {
42	  if (!value || typeof value !== 'object') return false;
43	  const candidate = value as Record<string, unknown>;
44	  return (
45	    typeof candidate.screeningId === 'number' &&
46	    Array.isArray(candidate.seats) &&
47	    typeof candidate.paid === 'boolean' &&
48	    typeof candidate.checkout === 'object' &&
49	    candidate.checkout !== null
50	  );
51	}
52	
53	export function loadBooking(): Booking | null {
54	  const raw = sessionStorage.getItem(STORAGE_KEY);
