11	  if (values.firstName === '') {
12	    errors.firstName = 'First name is required';
13	  } else if (values.firstName.length < 2) {
14	    errors.firstName = 'First name must be at least 2 characters';
15	  }
16	
17	  if (values.lastName === '') {
18	    errors.lastName = 'Last name is required';
19	  } else if (values.lastName.length < 2) {
20	    errors.lastName = 'Last name must be at least 2 characters';
21	  }
22	
23	  if (values.email === '') {
24	    errors.email = 'Email is required';
25	  } else if (!EMAIL_REGEX.test(values.email)) {
26	    errors.email = 'Enter a valid email address';
27	  }
28	
29	  if (values.confirmEmail === '') {
30	    errors.confirmEmail = 'Confirm email is required';
31	  } else if (values.confirmEmail !== values.email) {
32	    errors.confirmEmail = 'Email addresses do not match';
33	  }
34	
35	  if (values.phone !== '' && !PHONE_REGEX.test(values.phone)) {
